styles:
.page-post .post-body ul { list-style: none; margin: 0 0 1.5em; padding: 0;}
.page-post .post-body ul li { position: relative; padding-left: 26px; line-height: 1.58; margin-bottom: .85em;}
.page-post .post-body ul li::before { content: ""; position: absolute; left: 4px; top: .7em; width: 7px; height: 7px; border-radius: 50%; background: var(--red);}
.page-post .post-body ul li strong { color: var(--grey-900);}
